using System.IO;
using System.Collections;
using System.Diagnostics;
using System.Reflection;
using System.Runtime.Loader;
using System.Text.Json;
internal static class Checks
{
 const BindingFlags All=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 static Assembly host=null!;static Type engineType=null!,logType=null!;static string root="";static bool bounded;static readonly List<object> Results=[];static readonly List<string> Failures=[];
 static object? Get(object target,string name)=>target.GetType().GetField(name,All)!.GetValue(target);
 static void Set(object target,string name,object? value)=>target.GetType().GetField(name,All)!.SetValue(target,value);
 static void Static(string name,object value)=>engineType.GetField(name,All)!.SetValue(null,value);
 static int Count(string name)=>(int)engineType.GetField(name,All)!.GetValue(null)!;
 static void Assert(bool yes,string why){if(!yes)throw new InvalidOperationException(why);}
 static List<JsonElement> Rows(string path)=>!File.Exists(path)?[]:File.ReadAllLines(path).Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>JsonDocument.Parse(x.TrimStart('\uFEFF')).RootElement.Clone()).ToList();
 sealed class Fixture:IDisposable
 {
  internal readonly object Engine,Log;internal readonly string Dir;long stamp=Stopwatch.Frequency*1000;double cpu;
  internal Fixture(string name){Dir=Path.Combine(root,name);Directory.CreateDirectory(Dir);Log=Activator.CreateInstance(logType,All,null,[Dir,0],null)!;var options=host.GetType("YeManFanHost.HostOptions",true)!.GetMethod("Parse",All)!.Invoke(null,[Array.Empty<string>()]);Engine=Activator.CreateInstance(engineType,All,null,[options,Log],null)!;(Get(Engine,"runtimeDiagnosticsTimer") as Timer)?.Dispose();Set(Engine,"runtimeDiagnosticsTimer",null);Static("RuntimeThreadProbeCallsForFixture",0);Static("RuntimeThreadProbeDetailsForFixture",0);Static("RuntimeThreadProbeThrowForFixture",false);Set(Engine,"lastProcessCpuTime",TimeSpan.Zero);Set(Engine,"lastProcessSampleTimestamp",stamp);}
  internal string Flag=>Path.Combine(Dir,"fan-logging-enabled.flag");
  internal void Gate(string value)=>File.WriteAllText(Flag,value);
  internal int Probes=>Count("RuntimeThreadProbeCallsForFixture");internal int Details=>Count("RuntimeThreadProbeDetailsForFixture");
  internal long Maintenance=>(long)engineType.GetProperty("RuntimeLoopMaintenanceRunsForSelfTest",All)!.GetValue(Engine)!;
  internal List<JsonElement> Samples=>Rows((string)logType.GetProperty("Path",All)!.GetValue(Log)!).Where(x=>x.GetProperty("eventName").GetString()=="host.runtime-sample").Select(x=>x.GetProperty("details").Clone()).ToList();
  internal void Step(double percent=.3){stamp+=Stopwatch.Frequency*30;cpu+=percent/100d*Environment.ProcessorCount*30000d;Static("RuntimeThreadProbeTimestampForFixture",stamp);Static("RuntimeThreadProbeCpuMsForFixture",cpu);try{engineType.GetMethod("WriteRuntimeDiagnostics",All)!.Invoke(Engine,null);}catch(TargetInvocationException ex)when(ex.InnerException is not null){throw ex.InnerException;}}
  public void Dispose(){(Get(Engine,"runtimeDiagnosticsTimer") as Timer)?.Dispose();Set(Engine,"runtimeDiagnosticsTimer",null);((IDisposable)Engine).Dispose();}
 }
 static void Check(string name,Action work){try{work();Results.Add(new{name,ok=true});Console.WriteLine("PASS "+name);}catch(Exception error){Failures.Add(name+": "+error.Message);Results.Add(new{name,ok=false,error=error.Message});Console.WriteLine("FAIL "+name+": "+error.Message);}}
 static bool Attributed(JsonElement row)=>row.GetProperty("threadsAttributed").GetBoolean();
 static void Metadata(JsonElement row,bool baseline,double? interval){Assert(row.GetProperty("threadCpuIdKind").GetString()=="os-thread-id","managed/OS identity not explicit");Assert(row.GetProperty("threadCpuIntervalBasis").GetString()=="collection-start-to-start","thread interval basis absent");Assert(row.GetProperty("threadCpuBaseline").GetBoolean()==baseline,"baseline label wrong");var present=row.TryGetProperty("threadCpuIntervalMs",out var value);Assert(interval is null?(!present||value.ValueKind==JsonValueKind.Null):(present&&Math.Abs(value.GetDouble()-interval.Value)<.01),"thread CPU interval differs from attribution start interval");}
 public static int Main(string[] args){try{
  var dll=Path.GetFullPath(args[0]);root=Path.GetFullPath(args[1]);bounded=args[2]=="bounded";Directory.CreateDirectory(root);AssemblyLoadContext.Default.Resolving+=(_,name)=>{var p=Path.Combine(Path.GetDirectoryName(dll)!,name.Name+".dll");return File.Exists(p)?AssemblyLoadContext.Default.LoadFromAssemblyPath(p):null;};host=AssemblyLoadContext.Default.LoadFromAssemblyPath(dll);engineType=host.GetType("YeManFanHost.FanHostEngine",true)!;logType=host.GetType("YeManFanHost.HostDiagnosticLog",true)!;
  var capture=logType.GetProperty("SelfTestCaptureEnabled",All)!;capture.SetValue(null,false);
  Check("closed logging: count high CPU work discarded by the actual output gate",()=>{using var f=new Fixture("closed");for(int i=0;i<5;i++)f.Step(2);Assert(f.Probes==(bounded?0:5)&&f.Details==(bounded?0:5),"unexpected closed-gate heavy work");Assert(f.Samples.Count==0&&f.Maintenance==5,"closed gate changed output or skipped maintenance");Console.WriteLine($"OBSERVED closed-high-cpu: probes={f.Probes} details={f.Details} samples={f.Samples.Count} maintenance={f.Maintenance}");});
  Check("detailed logging: low CPU receives at most three thread snapshots",()=>{using var f=new Fixture("bounded");f.Gate("enabled");for(int i=0;i<10;i++)f.Step();Assert(f.Probes==(bounded?3:0)&&f.Details==10,"thread snapshot budget missing or unbounded");var rows=f.Samples;Assert(rows.Count==10&&rows.Count(Attributed)==(bounded?3:0),"low CPU observation coverage wrong");if(bounded){Metadata(rows[0],true,null);Metadata(rows[1],false,30000);Metadata(rows[2],false,30000);Assert(rows.Skip(3).All(x=>!Attributed(x)),"budget repeats without a new logging window");}Assert(f.Maintenance==10,"extra evidence changed maintenance windows");});
  Check("observed logging off/on starts one fresh bounded baseline",()=>{using var f=new Fixture("toggle");f.Gate("enabled");f.Step();f.Gate("disabled");f.Step(2);f.Gate("enabled");for(int i=0;i<4;i++)f.Step();Assert(f.Probes==(bounded?4:1),"off/on window not isolated");Assert(f.Samples.Count==5,"ordinary logging gate changed");if(bounded){Metadata(f.Samples[1],true,null);Assert(!Attributed(f.Samples[^1]),"new window did not stop at three");}});
  Check("high CPU attribution remains after the low CPU budget ends",()=>{using var f=new Fixture("high");f.Gate("enabled");for(int i=0;i<3;i++)f.Step();f.Step(2);f.Step(2);Assert(f.Probes==(bounded?5:2),"original high CPU threshold weakened");var rows=f.Samples;Assert(rows.TakeLast(2).All(Attributed),"high CPU threads lost");if(bounded)Assert(rows[^1].GetProperty("threadCpuCollectionReason").GetString()=="cpu-threshold","high CPU reason wrong");});
  Check("selftest capture keeps original closed-gate high CPU evidence",()=>{using var f=new Fixture("capture");logType.GetMethod("ResetSelfTestCapture",All)!.Invoke(null,null);capture.SetValue(null,true);try{f.Step(4.5);Assert(f.Probes==1&&f.Details==1&&f.Samples.Count==0,"selftest capture changed");var values=((IEnumerable)logType.GetProperty("SelfTestCaptured",All)!.GetValue(null)!).Cast<object>().ToArray();Assert(values.Length>=3,"sample/warning/hot-thread capture lost");}finally{capture.SetValue(null,false);logType.GetMethod("ResetSelfTestCapture",All)!.Invoke(null,null);}});
  Check("unreadable logging flag cannot skip maintenance or create probes",()=>{using var f=new Fixture("locked");f.Gate("enabled");using(var held=new FileStream(f.Flag,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){f.Step(2);}Assert(f.Probes==0&&f.Maintenance==1&&(int)Get(f.Engine,"runtimeSampleInFlight")! ==0,"flag exception changed responsibilities");f.Step();Assert(f.Probes==(bounded?1:0)&&f.Maintenance==2,"next sample cannot recover");});
  Check("failed thread collection consumes an attempt and retains honest time span",()=>{using var f=new Fixture("probe-fails");f.Gate("enabled");f.Step();Static("RuntimeThreadProbeThrowForFixture",true);f.Step();f.Step();f.Step();Assert(f.Probes==(bounded?3:0)&&f.Maintenance==4,"failed probe budget/maintenance wrong");if(bounded){var rows=f.Samples;Assert(rows.Count==3,"failed probe invented a runtime sample");Metadata(rows[1],false,60000);Assert(!Attributed(rows[2]),"failure retried indefinitely outside threshold");}});
  Check("diagnostic reentry never claims the prior owner or spends its budget",()=>{using var f=new Fixture("reentry");f.Gate("enabled");Set(f.Engine,"runtimeSampleInFlight",1);f.Step();Assert(f.Probes==0&&f.Maintenance==0&&(int)Get(f.Engine,"runtimeSampleInFlight")! ==1,"reentry ran work or retired another owner");Set(f.Engine,"runtimeSampleInFlight",0);f.Step();Assert(f.Probes==(bounded?1:0)&&f.Maintenance==1,"first valid attempt disappeared");});
  Check("logging value 1 remains supported with the same bounded window",()=>{using var f=new Fixture("legacy-flag");f.Gate("1");for(int i=0;i<5;i++)f.Step();Assert(f.Samples.Count==5&&f.Probes==(bounded?3:0),"legacy flag or budget changed");});
  Check("sampling never grants a lease, changes control, or loads HC",()=>{using var f=new Fixture("control");f.Gate("enabled");var state=Get(f.Engine,"state")!;var before=(string)state.GetType().GetProperty("State",All)!.GetValue(state)!;for(int i=0;i<5;i++)f.Step();Assert((string)state.GetType().GetProperty("State",All)!.GetValue(state)! == before,"sampling changed control state");Assert(state.GetType().GetProperty("Lease",All)!.GetValue(state) is null&&!(bool)state.GetType().GetProperty("HardwareWritesEnabled",All)!.GetValue(state)!,"sampling granted writes/lease");Assert(!AppDomain.CurrentDomain.GetAssemblies().Any(x=>x.GetName().Name=="HandheldCompanion"),"HC loaded during diagnostic-only gate");});
  var result=new{ok=Failures.Count==0,checks=Results.Count,mode=args[2],failures=Failures,results=Results,hardwareCalls=0,cpuBenchmark=false,scope="Actual scratch-instrumented runtime diagnostics/logging/maintenance scheduling; synthetic CPU/time/thread-probe only; own process metadata reads; no Host Main/HC/devices/user CPU timing"};var json=JsonSerializer.Serialize(result);File.WriteAllText(args[3],json);Console.WriteLine(json);return Failures.Count==0?0:1;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
